// Menyusun isi permintaan ke Google: membuat spreadsheet, lalu merapikan tampilannya.
const cfg = $('Pengaturan').first().json;

function warna(hex) {
  return {
    red: parseInt(hex.slice(1, 3), 16) / 255,
    green: parseInt(hex.slice(3, 5), 16) / 255,
    blue: parseInt(hex.slice(5, 7), 16) / 255,
  };
}

const kolom = [
  'Nomor WA', 'Nama', 'Perawatan', 'Waktu Diminta', 'Status',
  'Pertama Chat', 'Terakhir Chat', 'Diteruskan Pada', 'Pesan Terakhir',
  'Label', 'Catatan Admin',
];
const lebar = [140, 140, 170, 160, 180, 130, 130, 140, 300, 140, 240];
const status = ['Tanya-tanya', 'Menunggu Konfirmasi', 'Terkonfirmasi', 'Batal'];
const BARIS = 1000;

const petunjuk = [
  'PROSPEK & BOOKING (diisi otomatis oleh bot)',
  '',
  'Kolom Nomor WA sampai Pesan Terakhir diisi bot. Jangan mengubah judul kolom dan nama tab.',
  '',
  'Arti status:',
  '- Tanya-tanya: calon pasien baru bertanya, belum minta jadwal. (otomatis)',
  '- Menunggu Konfirmasi: bot sudah meneruskan permintaan booking ke admin. (otomatis)',
  '- Terkonfirmasi: nomor pasien sudah tercatat di sheet Booking. (otomatis, dicek tiap malam)',
  '- Batal: diisi ADMIN kalau pasien batal.',
  '',
  'Bot tidak akan menimpa status Batal atau Terkonfirmasi.',
  'Kalau pasien yang Batal mengajukan booking baru, statusnya kembali menjadi Menunggu Konfirmasi.',
  '',
  'Baris merah dan label "Lewat 24 jam": permintaan booking yang belum dikonfirmasi lebih dari 24 jam.',
  'Cek ke pasien, lalu catat booking-nya di sheet Booking, atau ubah status menjadi Batal.',
  '',
  'Kolom Catatan Admin bebas diisi dan tidak disentuh bot.',
];

const buat = {
  properties: {
    title: cfg.judul_file,
    locale: 'en_US',
    timeZone: 'Asia/Jakarta',
    autoRecalc: 'HOUR',
  },
  sheets: [
    {
      properties: {
        sheetId: 0,
        title: 'Prospek',
        gridProperties: { rowCount: BARIS, columnCount: kolom.length, frozenRowCount: 1 },
      },
      data: [{
        startRow: 0,
        startColumn: 0,
        rowData: [{
          values: kolom.map(k => ({
            userEnteredValue: { stringValue: k },
            userEnteredFormat: {
              backgroundColor: warna('#1F4E78'),
              textFormat: { bold: true, foregroundColor: warna('#FFFFFF') },
              verticalAlignment: 'MIDDLE',
            },
          })),
        }],
      }],
    },
    {
      properties: {
        sheetId: 1,
        title: 'Petunjuk',
        gridProperties: { rowCount: petunjuk.length + 5, columnCount: 1 },
      },
      data: [{
        startRow: 0,
        startColumn: 0,
        rowData: petunjuk.map((t, i) => ({
          values: [{
            userEnteredValue: { stringValue: t },
            userEnteredFormat: i === 0 ? { textFormat: { bold: true, fontSize: 12 } } : {},
          }],
        })),
      }],
    },
  ],
};

function rentang(kolAwal, kolAkhir) {
  return { sheetId: 0, startRowIndex: 1, endRowIndex: BARIS, startColumnIndex: kolAwal, endColumnIndex: kolAkhir };
}
const semuaBaris = rentang(0, kolom.length);
const kolStatus = rentang(4, 5);

const requests = [
  // Dropdown status
  { setDataValidation: {
      range: kolStatus,
      rule: {
        condition: { type: 'ONE_OF_LIST', values: status.map(s => ({ userEnteredValue: s })) },
        strict: true,
        showCustomUi: true,
      },
  } },
  // Nomor WA disimpan sebagai teks supaya tidak berubah jadi angka 6,28E+12
  { repeatCell: {
      range: rentang(0, 1),
      cell: { userEnteredFormat: { numberFormat: { type: 'TEXT' } } },
      fields: 'userEnteredFormat.numberFormat',
  } },
  // Kolom tanggal dan jam
  { repeatCell: {
      range: rentang(5, 8),
      cell: { userEnteredFormat: { numberFormat: { type: 'DATE_TIME', pattern: 'dd/mm/yyyy hh:mm' } } },
      fields: 'userEnteredFormat.numberFormat',
  } },
  // Pesan terakhir dan catatan admin dibungkus supaya tidak memanjang
  { repeatCell: {
      range: rentang(8, 9),
      cell: { userEnteredFormat: { wrapStrategy: 'WRAP' } },
      fields: 'userEnteredFormat.wrapStrategy',
  } },
  { repeatCell: {
      range: rentang(10, 11),
      cell: { userEnteredFormat: { wrapStrategy: 'WRAP' } },
      fields: 'userEnteredFormat.wrapStrategy',
  } },
  // Baris merah: menunggu konfirmasi lebih dari 24 jam
  { addConditionalFormatRule: {
      index: 0,
      rule: {
        ranges: [semuaBaris],
        booleanRule: {
          condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=AND($E2="Menunggu Konfirmasi",$H2<>"",NOW()-$H2>1)' }] },
          format: { backgroundColor: warna('#F8D7DA') },
        },
      },
  } },
  // Status Terkonfirmasi berwarna hijau
  { addConditionalFormatRule: {
      index: 1,
      rule: {
        ranges: [kolStatus],
        booleanRule: {
          condition: { type: 'TEXT_EQ', values: [{ userEnteredValue: 'Terkonfirmasi' }] },
          format: { backgroundColor: warna('#D4EDDA') },
        },
      },
  } },
  // Baris Batal berwarna abu-abu
  { addConditionalFormatRule: {
      index: 2,
      rule: {
        ranges: [semuaBaris],
        booleanRule: {
          condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=$E2="Batal"' }] },
          format: { textFormat: { foregroundColor: warna('#9E9E9E') } },
        },
      },
  } },
  // Lebar kolom
  ...lebar.map((px, i) => ({ updateDimensionProperties: {
      range: { sheetId: 0, dimension: 'COLUMNS', startIndex: i, endIndex: i + 1 },
      properties: { pixelSize: px },
      fields: 'pixelSize',
  } })),
  { updateDimensionProperties: {
      range: { sheetId: 1, dimension: 'COLUMNS', startIndex: 0, endIndex: 1 },
      properties: { pixelSize: 760 },
      fields: 'pixelSize',
  } },
];

return [{ json: { buat, rapikan: { requests }, email_robot: String(cfg.email_robot || '').trim() } }];
